import{_ as p,h as l,i as e,c as i,v as t,p as m,x as r,m as n,e as s,S as d}from"./chunks/framework.Dvtg8yj2.js";const b=JSON.parse('{"title":"学习率：warmup、余弦、WSD","description":"","frontmatter":{"title":"学习率：warmup、余弦、WSD","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/lr-schedule.md","filePath":"llm/lr-schedule.md","lastUpdated":1788454257000}'),h={name:"llm/lr-schedule.md"};function c(u,a,W,_,D,w){const o=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="学习率-warmup、余弦、wsd" tabindex="-1">学习率：warmup、余弦、WSD <a class="header-anchor" href="#学习率-warmup、余弦、wsd" aria-label="Permalink to &quot;学习率：warmup、余弦、WSD&quot;">​</a></h1><div class="epigraph"><p>先把学习率抬到能走的步长，再决定后面是按总步数余弦落下，还是先走一段常数、临停再衰减。</p><footer>—— 余弦日程见 Loshchilov &amp; Hutter；WSD 见 MiniCPM 等预训练报告</footer></div><p>预训练几乎从不用恒定学习率贯穿全程。常见骨架是三段：从接近零线性升到峰值（warmup），在峰值附近训练，再把学习率降下来（decay）。GPT-3 一类配方把后两段收成「warmup + 余弦」，余弦的自变量是「已经走了总预算的几分之几」，因此必须预先知道总步数 \\(T\\)。WSD（warmup-stable-decay）把中间改成常数稳定段，只在计划结束前用很短的一段衰减收尾。它改的不是优化器，是「你何时必须承诺总时长」。本篇只谈学习率作为时间函数，不重写 Adam 的矩，也不谈 μP 里学习率如何随宽度变——那是另一篇的尺度，不是时间。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>随机梯度的噪声尺度随 batch 变，损失曲面在初始化附近又特别陡。一上来就用峰值学习率，梯度裁剪会持续触发，Adam 的二阶矩还是空的，半精度更容易溢出。warmup 把有效步长从近零抬到配方给出的峰值，让矩统计与残差流的尺度先进入可工作区间。</p><p>衰减要解决的是另一件事：训练后半段若仍用峰值，权重在极小值附近来回抖动，损失曲线变毛，末期评测不稳。余弦把学习率平滑降到 \\(\\eta_{\\min}\\)（常取峰值的 10% 或 0），形状由总步数锁死。问题是预训练常常改主意：数据配比要加一段、算力突然多了两天、想从中间检查点续训。余弦已经按旧的 \\(T\\) 走到很低，再往下训要么学习率近乎零，要么人为把日程拉长、等于改写已经走过的曲线。需要一种日程：中间检查点仍然「在峰值上」，停训的决策可以后置。</p><h3 id="warmup-在补什么" tabindex="-1">Warmup 在补什么 <a class="header-anchor" href="#warmup-在补什么" aria-label="Permalink to &quot;Warmup 在补什么&quot;">​</a></h3><p>线性 warmup 是 \\(\\eta(t)=\\eta_{\\mathrm{peak}}\\cdot t/W\\)（\\(t\\le W\\)）。\\(W\\) 常用总步数的 1%–5%，或固定若干 token。它补偿的对象随架构变。Post-LN 深层对 warmup 更苛刻，因为残差通路被层归一化压过；Pre-LN / Pre-RMSNorm 对短 warmup 更宽容，但 Adam 的 \\(v\\) 仍需要样本，嵌入层的范数仍可能在前几步被大学习率拉飞。warmup 不是「让曲线好看的仪式」，是给二阶矩与激活尺度一个缓冲。过短会在前几千步看到梯度范数尖刺；过长则浪费本可以在峰值上走的 token。</p><p><span class="marginnote">把 warmup 理解成「从零开始所以必须慢」并不准确。许多实现允许 warmup 起点是峰值的一个很小分数而不是绝对零。真正不能省的是：前若干步不要用未经校准的满学习率去推尚未稳定的矩与尚未归一的残差流。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记峰值学习率为 \\(\\eta_{\\mathrm{peak}}\\)，总步数 \\(T\\)，warmup 步数 \\(W\\)。</p><p><strong>余弦</strong>（warmup 之后）：</p> \\[\\eta(t)=\\eta_{\\min}+\\frac{1}{2}(\\eta_{\\mathrm{peak}}-\\eta_{\\min})\\bigl(1+\\cos\\pi\\frac{t-W}{T-W}\\bigr). \\]<p>这是 SGDR 里余弦退火的单周期形式，GPT-3、PaLM、LLaMA 早期配方的默认。\\(T\\) 必须在开训时写进配置。中途改 \\(T\\)，已经走过的 \\(\\eta\\) 不再落在同一条余弦上，续训检查点与「假如一开始就用新 \\(T\\)」不可比。</p><p><strong>WSD</strong>：warmup 之后进入稳定段 \\(\\eta(t)=\\eta_{\\mathrm{peak}}\\)，直到衰减起点 \\(T_{\\mathrm{decay}}\\)，再在剩余 \\(D\\) 步里线性或余弦降到 \\(\\eta_{\\min}\\)。稳定段可以任意延长：你加数据、加步数，只是推迟 \\(T_{\\mathrm{decay}}\\)。衰减段相对全程很短，常见是最后 10% 或更少，具体比例随报告而变，没有一条必须遵守的常数。MiniCPM 等预训练报告把这种三段式叫 warmup-stable-decay；关于「计算最优不必绑定固定时长」的后续工作也采用同类日程。若最早命名归属有争议，以三个阶段的操作定义为准。</p>',15)),(e(),m(d,null,{default:r(()=>[s(o,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20W%5B%22Warmup%20%E5%8D%87%E5%88%B0%E5%B3%B0%E5%80%BC%22%5D%20--%3E%20C%5B%22%E4%BD%99%E5%BC%A6%EF%BC%9A%E6%8C%89%E6%80%BB%E6%AD%A5%E6%95%B0%20T%20%E8%90%BD%E4%B8%8B%22%5D%0A%20%20W%20--%3E%20S%5B%22WSD%20%E7%A8%B3%E5%AE%9A%E6%AE%B5%EF%BC%9A%E5%B8%B8%E6%95%B0%E5%B3%B0%E5%80%BC%22%5D%0A%20%20S%20--%3E%20D%5B%22%E7%9F%AD%E8%A1%B0%E5%87%8F%20%2F%20cooldown%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h3 id="余弦衰减绑定了总步数" tabindex="-1">余弦衰减绑定了总步数 <a class="header-anchor" href="#余弦衰减绑定了总步数" aria-label="Permalink to &quot;余弦衰减绑定了总步数&quot;">​</a></h3><p>余弦的优点是可复现：同样的 \\(T\\)、\\(W\\)、\\(\\eta_{\\mathrm{peak}}\\)，曲线唯一。做扩展律、扫学习率时，这条唯一性很值钱。代价是所有中间检查点都处在「已经开始降温」的状态。若你想用 50% 进度的检查点做下游，它对应的有效学习率已经明显低于峰值，和「完整训完再评」不是同一超参点。把余弦在 50% 处截断当成品模型，等于用了一条没走完的退火，往往偏欠拟合。</p><h3 id="wsd-先走稳-再决定何时收" tabindex="-1">WSD：先走稳，再决定何时收 <a class="header-anchor" href="#wsd-先走稳-再决定何时收" aria-label="Permalink to &quot;WSD：先走稳，再决定何时收&quot;">​</a></h3><p>稳定段上，每个检查点分享同一学习率，差别主要是看到的 token 数。要做「多训会不会继续降损」，直接比稳定段上的点即可，不必先把日程重归一化。真正改变模型的是最后一段衰减：学习率下降后，损失通常会再掉一截，像一次 cooldown。同一条稳定段可以分叉出多次衰减——例如在 100B、300B token 各做一次短衰减，得到两个成品——而不必重训前面。这是 WSD 相对余弦最实质的工程差异。</p><p>衰减用线性还是余弦，公开配方两者都有。短衰减时二者差别小于峰值选错；长衰减会重新引入「你还是得猜 \\(D\\)」的问题，WSD 的优势被吃掉。稳定段过早衰减，和余弦没有本质区别；过晚衰减，末期仍在峰值抖动，评测方差大。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>学习率乘在优化器给出的方向上。对 AdamW，有效步长还被 \\(\\sqrt{v}\\) 除过；对 Muon，方向已经被正交化。日程改变的是这条方向的<strong>全局标量</strong>，不改变方向如何被预条件。因此「换了 WSD 就可以把峰值提高一倍」没有根据：峰值仍受梯度爆炸、损失尖峰、混合精度溢出约束。WSD 解放的是时间轴上的承诺，不是稳定性上限。</p><p>Warmup 与 Adam 矩的相互作用：前几步 \\(v\\) 接近 0，未修正的 Adam 会给出巨大步长，warmup 把 \\(\\eta\\) 压住；偏差修正（bias correction）本身也在抬早期有效学习率，二者叠加时，真正的早期步长不是 \\(\\eta(t)\\) 曲线看起来那么小。实现若关掉偏差修正，同样的 \\(W\\) 会显得更必要。写复现时要写明这一点，否则抄了 \\(W\\) 却抄错了 Adam 选项。</p><p><span class="marginnote">WSD 的稳定段不是「不用调度」。它是调度里最长的一块取常数。数据配比若在稳定段中途切换，等于在同一学习率下改变梯度分布，损失可能出现台阶；那是数据问题，不要第一反应去改衰减形状。</span></p><h3 id="衰减段在优化里做什么" tabindex="-1">衰减段在优化里做什么 <a class="header-anchor" href="#衰减段在优化里做什么" aria-label="Permalink to &quot;衰减段在优化里做什么&quot;">​</a></h3><p>直观图像是：峰值学习率对应较大的有效噪声，有利于跳出差盆地、继续吃数据；衰减降低噪声，让参数在当前盆地里收敛，训练损失与验证损失的间隙常在 cooldown 时收窄。这不是严格的温度退火定理，但和「末期小学习率」的经验一致。若衰减过快，参数来不及在新步长下调整，cooldown 的收益变薄；若衰减过慢，又回到余弦那种必须早早开始降温的处境。WSD 把「探索」和「收敛」在时间上拆开，余弦把二者编进同一条光滑曲线。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>没有一种日程能补救峰值选错。峰值过高，warmup 再长也会在进入稳定段后尖峰；过低，余弦和 WSD 都只是在错误的尺度上走完全程。扫学习率应在短稳定段或短余弦上做，而不是先做完整 WSD 再回头。</p><p>与 batch size 的线性缩放（学习率随 batch 正比增加）是另一条轴。加大 batch 却不改峰值，等于降低噪声、也降低步长；WSD 不会自动替你做这条换算。梯度累积改变的是有效 batch，日程应按<strong>优化器步</strong>计，不是按 microbatch 计。把 warmup 写成「前 N 个 microbatch」会在改流水线切分时把 \\(W\\) 悄悄改掉。</p><p>余弦仍适合总 token 预算锁死、要和其他论文对齐曲线的实验。WSD 适合持续预训练、中途加数据、从稳定段分叉多个成品。把已经按余弦训到末期的检查点改接 WSD 稳定段，学习率必须先抬回去，这不是无缝切换，等于一次新的超参实验。</p><p><span class="marginnote">不要用验证损失在余弦末期的骤降，去证明「余弦比 WSD 更能学」。那截骤降往往来自衰减本身。WSD 把同样的骤降推迟到你选择的 cooldown。公平比较应看冷却后的点，或看稳定段上同等 token 的点，而不是把未冷却的常数学习率曲线和已冷却的余弦终点比。</span></p><p>推理期的温度、解码学习率（若有）与训练日程无关。训练末期 \\(\\eta\\) 接近 0 不表示模型「学完了」，只表示按这条日程不再更新。续训必须重新给出 warmup 或直接回到稳定段峰值，并声明与原日程的关系。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Warmup 把学习率从近零抬到峰值，给 Adam 矩、激活尺度和早期稳定性留缓冲。</li><li>余弦把衰减绑在预先给定的总步数 \\(T\\) 上，中间检查点已经在降温，续训改 \\(T\\) 会破坏曲线。</li><li>WSD 是 warmup–stable–decay：中间常数峰值，临停再短衰减，稳定段可延长、可分叉多次 cooldown。</li><li>日程只缩放更新的全局标量；峰值是否稳、是否与 batch 对齐，仍要单独选。</li><li>比较余弦与 WSD，应对齐冷却后的模型，而不是用未衰减的稳定段去打已退火的终点。</li><li>出处：Loshchilov &amp; Hutter 的余弦退火；Brown 等 GPT-3 配方中的 warmup + 余弦；WSD 见 MiniCPM 等预训练报告，以及关于不固定训练时长的后续扩展律工作。</li></ul>',19))])}const B=p(h,[["render",c]]);export{b as __pageData,B as default};
